"""Preserve previous named subtypes; use major+marker only for unfinished annotations."""
import json,hashlib,re
from datetime import datetime,timezone
import numpy as np,pandas as pd
r=PROJECT_ROOT/'runs/20261106_v7_publication_marker_annotation_v1';o=r/'stage_h_selective_subtype_restore_v4';o.mkdir(exist_ok=False)
previous=PROJECT_ROOT/'runs/20261106_v7_B_unresolved_review_v1/stage_g_consolidated_annotation/current_annotation_all_cells_PRIVATE.pkl.gz'
q=pd.read_pickle(previous);b=pd.read_pickle(r/'stage_c4_harmonized_identity_freeze/annotation_all_cells_with_release_status_PRIVATE.pkl.gz');assert q.index.equals(b.index)
keep=q.current_primary_QC_keep.to_numpy(bool);old=q.frozen_label.astype(str);placeholder=old.str.contains('unresolved|coarse|provisional|pending|boundary|unknown|ambiguous',case=False,regex=True).to_numpy()
# Existing names are retained, not re-qualified by a broad component gate.
# A completed earlier lineage refit may explicitly contradict the old parent; retain that correction.
prior_refit=q.annotation_layer.astype(str).eq('rare_four_working_20261106').to_numpy();prior_broad=q.identity_review_status.astype(str).eq('broad_working').to_numpy();same_prior_parent=q.current_parent.astype(str).to_numpy()==q.frozen_parent.astype(str).to_numpy()
refit_exception=(~placeholder)&prior_refit&~(prior_broad&same_prior_parent)
retain=keep&~placeholder&~refit_exception
fallback=keep&~retain&b.annotation_frozen.to_numpy(bool)
selected=retain|fallback;assert not (retain&fallback).any()
t=b.copy();t['final_annotation']=pd.Series(pd.NA,index=t.index,dtype=object);t['final_parent']=pd.Series(pd.NA,index=t.index,dtype=object);t['representative_markers']=pd.Series(pd.NA,index=t.index,dtype=object);t['annotation_resolution']=pd.Series(pd.NA,index=t.index,dtype=object);t['label_application']='outside_selected_annotation_view';t['evidence_basis_v4']='not_selected_in_this_view'
t.loc[retain,'final_annotation']=old.loc[retain].to_numpy();t.loc[retain,'final_parent']=q.loc[retain,'frozen_parent'].astype(str).to_numpy();t.loc[retain,'representative_markers']='';t.loc[retain,'annotation_resolution']='previous_named_subtype_or_classification_retained';t.loc[retain,'label_application']='retain_previous_named_annotation';t.loc[retain,'evidence_basis_v4']='Previous named V7 annotation retained per user correction; inherited acceptance only, not a new subtype validation.'
t.loc[fallback,'final_annotation']=b.loc[fallback,'final_annotation'].astype(str).to_numpy();t.loc[fallback,'final_parent']=b.loc[fallback,'final_parent'].astype(str).to_numpy();t.loc[fallback,'representative_markers']=b.loc[fallback,'representative_markers'].astype(str).to_numpy();t.loc[fallback,'annotation_resolution']='major_identity_plus_markers';t.loc[fallback,'label_application']='unfinished_label_major_marker_fallback';t.loc[fallback&refit_exception,'label_application']='previous_refit_parent_correction_major_marker';t.loc[fallback,'evidence_basis_v4']=b.loc[fallback,'freeze_basis'].astype(str).to_numpy()
t['annotation_frozen']=selected;t['identity_freeze_accepted']=selected;t['release_version']='V7_selective_subtype_marker_20261106_v4';t['prior_named_annotation_retained']=retain;t['previous_refit_contradicts_named_parent']=refit_exception;t['broad_v3_membership_diagnostic']=b.annotation_frozen.to_numpy();t['broad_v3_parent_diagnostic']=b.final_parent.astype(object);t['broad_v3_label_diagnostic']=b.final_annotation.astype(object);t['current_parent']=q.current_parent.astype(object);t['previous_annotation_layer']=q.annotation_layer.astype(object);t['previous_identity_review_status']=q.identity_review_status.astype(object)
# Related grain changes are diagnostic, not evidence that a previously named subtype is false.
compatible={'Macrophage':{'Myeloid'},'Monocyte':{'Myeloid'},'Neural':{'Neural','Glial'}}
oldp=q.frozen_parent.astype(str).to_numpy();newp=b.final_parent.astype(str).to_numpy();compat=oldp==newp
for p,allowed in compatible.items():compat|=(oldp==p)&np.isin(newp,list(allowed))
t['broad_parent_difference_needs_review']=retain&b.annotation_frozen.to_numpy()&~compat
assert np.array_equal(t.loc[retain,'final_annotation'].astype(str).to_numpy(),old.loc[retain].to_numpy());assert not t.loc[selected,'final_annotation'].astype(str).str.contains('unresolved|coarse|provisional|pending|boundary|unknown|ambiguous',case=False).any();assert t.final_annotation.notna().equals(t.annotation_frozen)
for col in t.select_dtypes(include=object):t[col]=t[col].astype('category')
t.to_pickle(o/'all_axis_selective_annotation_with_history_PRIVATE.pkl.gz',compression={'method':'gzip','compresslevel':1})
f=pd.DataFrame(index=t.index[selected]);f.index.name='cell_id'
for target,source in [('final_annotation','final_annotation'),('major_cell_type','final_parent'),('representative_markers','representative_markers'),('annotation_resolution','annotation_resolution'),('annotation_application','label_application'),('evidence_basis','evidence_basis_v4'),('prior_named_annotation_retained','prior_named_annotation_retained'),('broad_parent_difference_needs_review','broad_parent_difference_needs_review'),('malignancy_context_status','malignancy_context_status'),('raw_IFN_programme_positive','raw_IFN_programme_positive'),('raw_cycling_programme_positive','raw_cycling_programme_positive'),('raw_heat_shock_programme_positive','raw_heat_shock_programme_positive')]:f[target]=t.loc[selected,source]
f['annotation_version']='V7_selective_subtype_marker_20261106_v4'
for col in q:
 if col.startswith('frozen_') and ('malignan' in col or 'evidence_version' in col):f[col.removeprefix('frozen_')]=q.loc[selected,col]
f.to_pickle(o/'annotation_frozen_V7_selective_subtype_20261106_v4_PRIVATE.pkl.gz',compression={'method':'gzip','compresslevel':1});f.to_csv(o/'annotation_frozen_V7_selective_subtype_20261106_v4_PRIVATE.tsv.gz',sep='\t',compression={'method':'gzip','compresslevel':1},na_rep='NA')
f.groupby(['major_cell_type','final_annotation','annotation_resolution','annotation_application'],observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'corrected_final_label_counts.tsv',sep='\t',index=False)
cross=pd.DataFrame({'previous_named_parent':q.frozen_parent.astype(str),'previous_label':old,'corrected_parent':t.final_parent.astype(object),'corrected_label':t.final_annotation.astype(object),'QC_action':q.current_QC_action.astype(str),'application':t.label_application.astype(str),'prior_refit_exception':refit_exception},index=t.index);cross.groupby(list(cross.columns),observed=True,dropna=False).size().rename('n_cells').reset_index().to_csv(o/'all_previous_labels_correction_crosswalk.tsv',sep='\t',index=False,na_rep='')
label_rows=[]
for label,ids in q.loc[keep&~placeholder].groupby('frozen_label',observed=True).groups.items():
 loc=q.index.get_indexer(ids);label_rows.append({'previous_label':str(label),'n_QC_keep':len(loc),'n_original_name_retained':int(retain[loc].sum()),'n_previous_refit_parent_exception':int(refit_exception[loc].sum()),'n_selected_after_correction':int(selected[loc].sum()),'n_not_selected':int((~selected[loc]).sum()),'n_retained_outside_previous_v3_broad_mask':int((retain[loc]&~b.annotation_frozen.to_numpy()[loc]).sum())})
pd.DataFrame(label_rows).to_csv(o/'previous_named_annotation_preservation_audit.tsv',sep='\t',index=False)
out={'status':'selective_subtype_restore_written_pending_independent_audit','UTC':datetime.now(timezone.utc).isoformat(),'annotation_version':'V7_selective_subtype_marker_20261106_v4','n_original_axis':len(t),'n_QC_keep':int(keep.sum()),'n_previous_named_QC_keep':int((keep&~placeholder).sum()),'n_previous_named_annotation_retained':int(retain.sum()),'n_prior_refit_parent_exceptions':int((keep&refit_exception).sum()),'n_retained_outside_previous_broad_v3_mask':int((retain&~b.annotation_frozen.to_numpy()).sum()),'n_major_marker_fallback':int(fallback.sum()),'n_selected':int(selected.sum()),'n_final_labels':int(f.final_annotation.nunique()),'n_QC_keep_outside_corrected_view':int((keep&~selected).sum()),'n_previously_named_labels_retained':int(old.loc[retain].nunique()),'n_new_subtype_validation_claims':0,'QC_changed':False,'all_atlas_publication_acceptance':False,'v3_role':'Historical broad-identity diagnostic layer only; superseded as complete-annotation display.','files':[{'name':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in o.iterdir() if p.is_file()]};(o/'complete.json').write_text(json.dumps(out,indent=2));print(json.dumps({k:v for k,v in out.items() if k!='files'}))
